internal record Call (
    string @contractAddress, 
    string @entrypoint, 
    string[] @calldata
) {
}

class FfiConverterTypeCall: FfiConverterRustBuffer<Call> {
    public static FfiConverterTypeCall INSTANCE = new FfiConverterTypeCall();

    public override Call Read(BigEndianStream stream) {
        return new Call(
            @contractAddress: FfiConverterString.INSTANCE.Read(stream),
            @entrypoint: FfiConverterString.INSTANCE.Read(stream),
            @calldata: FfiConverterSequenceString.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(Call value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.@contractAddress)
            + FfiConverterString.INSTANCE.AllocationSize(value.@entrypoint)
            + FfiConverterSequenceString.INSTANCE.AllocationSize(value.@calldata);
    }

    public override void Write(Call value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.@contractAddress, stream);
            FfiConverterString.INSTANCE.Write(value.@entrypoint, stream);
            FfiConverterSequenceString.INSTANCE.Write(value.@calldata, stream);
    }
}





